const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const pacificPalisades = ee.Geometry.Point(-118.5583, 34.0333); // Approximate center of Pacific Palisades

  // Function to get a point at a given bearing and distance
  // (Simplified approximation for small distances, good enough for 50km)
  const getOffsetPoint = (origin, distanceKm, bearingDeg) => {
    const lat = origin.coordinates().get(1);
    const lon = origin.coordinates().get(0);
    const distanceMeters = distanceKm * 1000;

    // Earth's radius in meters
    const R = 6378137;

    const latRad = ee.Number(lat).multiply(Math.PI / 180);
    const lonRad = ee.Number(lon).multiply(Math.PI / 180);
    const bearingRad = ee.Number(bearingDeg).multiply(Math.PI / 180);

    const newLatRad = ee.Number(latRad).add(
      ee.Number(distanceMeters).multiply(ee.Number(bearingRad).cos()).divide(R)
    );
    const newLonRad = ee.Number(lonRad).add(
      ee.Number(distanceMeters).multiply(ee.Number(bearingRad).sin()).divide(R).divide(newLatRad.cos())
    );

    return ee.Geometry.Point(newLonRad.multiply(180 / Math.PI), newLatRad.multiply(180 / Math.PI));
  };

  // Region 1: 50 km west of Pacific Palisades (bearing 270 degrees)
  const region1Center = getOffsetPoint(pacificPalisades, 50, 270);
  const region1 = region1Center.buffer(5000); // 5 km radius region

  // Region 2: 50 km southwest of Pacific Palisades (bearing 225 degrees)
  const region2Center = getOffsetPoint(pacificPalisades, 50, 225);
  const region2 = region2Center.buffer(5000); // 5 km radius region

  const date = '2025-01-07'; // Specific date

  // 2. Data Acquisition
  let no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFLINE/L3_NO2')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(region1.union(region2))
    .select('tropospheric_NO2_column_number_density')
    .filter(ee.Filter.gt('qa_value', 0.75)); // Filter for good quality data

  // Check for empty collection (C1)
  const collectionSize = await no2Collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No Sentinel-5P NO2 images found for January 7, 2025 afternoon in the specified regions.");
    console.log("C1");
    return;
  }
  console.log(`Images found: ${collectionSize}`);

  const image = no2Collection.mean(); // Take the mean if multiple images exist

  // 3. Processing & Calculation
  const scale = 1000; // Resolution in meters for reduction
  const maxPixels = 1e9;

  // Calculate NO2 concentration for Region 1
  const meanNO2_region1_obj = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region1,
    scale: scale,
    maxPixels: maxPixels
  }).getInfo();

  const meanNO2_region1 = meanNO2_region1_obj ? meanNO2_region1_obj['tropospheric_NO2_column_number_density'] : null;

  // Calculate pixel count for Region 1 to detect C2
  const countPixels_region1_obj = await image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region1,
    scale: scale,
    maxPixels: maxPixels
  }).getInfo();

  const countPixels_region1 = countPixels_region1_obj ? countPixels_region1_obj['tropospheric_NO2_column_number_density'] : 0;

  // Calculate NO2 concentration for Region 2
  const meanNO2_region2_obj = await image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region2,
    scale: scale,
    maxPixels: maxPixels
  }).getInfo();

  const meanNO2_region2 = meanNO2_region2_obj ? meanNO2_region2_obj['tropospheric_NO2_column_number_density'] : null;

  // Calculate pixel count for Region 2 to detect C2
  const countPixels_region2_obj = await image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region2,
    scale: scale,
    maxPixels: maxPixels
  }).getInfo();

  const countPixels_region2 = countPixels_region2_obj ? countPixels_region2_obj['tropospheric_NO2_column_number_density'] : 0;

  // 4. Validation & Final Answer

  if (countPixels_region1 === 0 || countPixels_region2 === 0) {
    console.log("No valid pixels remain after masking for one or both regions.");
    console.log(`Region 1 valid pixels: ${countPixels_region1}`);
    console.log(`Region 2 valid pixels: ${countPixels_region2}`);
    console.log("C2");
    return;
  }

  if (meanNO2_region1 === null || isNaN(meanNO2_region1) ||
      meanNO2_region2 === null || isNaN(meanNO2_region2)) {
    console.log("Calculation resulted in None/NaN for one or both regions.");
    console.log(`Region 1 NO2: ${meanNO2_region1}`);
    console.log(`Region 2 NO2: ${meanNO2_region2}`);
    console.log("C3");
    return;
  }

  console.log(`Region 50km west (NO2: ${meanNO2_region1.toExponential(2)} mol/m^2, Pixels: ${countPixels_region1})`);
  console.log(`Region 50km southwest (NO2: ${meanNO2_region2.toExponential(2)} mol/m^2, Pixels: ${countPixels_region2})`);

  if (meanNO2_region1 > meanNO2_region2) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
